/// The assistant phrasings dataset — Phase 6 (master prompt §9).
///
/// Loads `assets/assistant_phrasings.json` (generated by
/// `tools/generate_phrasings.py` from structured templates × DB-verified
/// entities; 5,203 phrasings, 15 categories, template-level train /
/// validation / test splits with no leakage) and matches a user question
/// against it by normalised token overlap.
///
/// This is INTENT MATCHING, not model training: the match is shown to the
/// user as the closest known phrasing and NEVER changes the retrieved
/// evidence or the intent (intent stays keyword-based, see [intent.dart]).
/// The file, the UI and the report all say so explicitly. No claim of
/// training a language model is made anywhere.
library;

import 'dart:convert';

import 'package:flutter/services.dart' show rootBundle;

import 'intent.dart' show assistantContentTerms;

/// Asset path of the bundled phrasings dataset (declared in pubspec.yaml).
const String kPhrasingsAssetPath = 'assets/assistant_phrasings.json';

/// One phrasing from the dataset.
class PhrasingEntry {
  const PhrasingEntry({
    required this.id,
    required this.text,
    required this.category,
    required this.templateId,
    required this.split,
    required this.referenceStatus,
  });

  factory PhrasingEntry.fromJson(Map<String, Object?> json) {
    return PhrasingEntry(
      id: (json['id'] as String?) ?? '',
      text: (json['text'] as String?) ?? '',
      category: (json['category'] as String?) ?? '',
      templateId: (json['template_id'] as String?) ?? '',
      split: (json['split'] as String?) ?? '',
      referenceStatus: (json['reference_status'] as String?) ?? '',
    );
  }

  final String id;
  final String text;
  final String category;
  final String templateId;

  /// train / validation / test (template-level split, no leakage).
  final String split;

  /// "verified" when every reference hadith was found in the DB;
  /// otherwise names exactly what is unavailable (e.g.
  /// "unavailable_no_narrator_data").
  final String referenceStatus;
}

/// Load the bundled dataset. Returns an empty list (never throws) when
/// the asset is missing or malformed — intent matching then simply has
/// no phrasings to show, and keyword intent still works.
Future<List<PhrasingEntry>> loadPhrasings() async {
  try {
    final raw = await rootBundle.loadString(kPhrasingsAssetPath);
    final decoded = jsonDecode(raw);
    if (decoded is! Map<String, Object?>) return const <PhrasingEntry>[];
    final items = decoded['phrasings'];
    if (items is! List) return const <PhrasingEntry>[];
    return items
        .whereType<Map<String, Object?>>()
        .map(PhrasingEntry.fromJson)
        .where((p) => p.text.isNotEmpty)
        .toList();
  } catch (_) {
    return const <PhrasingEntry>[];
  }
}

/// Parse the dataset from already-loaded JSON text (used by tests).
List<PhrasingEntry> parsePhrasings(String rawJson) {
  try {
    final decoded = jsonDecode(rawJson);
    if (decoded is! Map<String, Object?>) return const <PhrasingEntry>[];
    final items = decoded['phrasings'];
    if (items is! List) return const <PhrasingEntry>[];
    return items
        .whereType<Map<String, Object?>>()
        .map(PhrasingEntry.fromJson)
        .where((p) => p.text.isNotEmpty)
        .toList();
  } catch (_) {
    return const <PhrasingEntry>[];
  }
}

/// Token-overlap score between a question and a phrasing: shared CONTENT
/// tokens over question content tokens (retrieval stopwords removed, so
/// "في" and "من" can never inflate the score). 1.0 means the question's
/// content tokens are all covered by the phrasing.
double phrasingOverlapScore(String query, String phrasing) {
  final q = assistantContentTerms(query).toSet();
  if (q.isEmpty) return 0;
  final p = assistantContentTerms(phrasing).toSet();
  return q.intersection(p).length / q.length;
}

/// The closest known phrasing to [query], or null when no phrasing
/// shares at least half the question's content tokens. Scoring uses
/// content terms only: "أحاديث في المريخ" must NOT match
/// "أحاديث في الصلاة" (their only shared tokens are question words).
/// Pure function — unit-tested.
PhrasingEntry? matchPhrasing(String query, List<PhrasingEntry> entries) {
  final qTokens = assistantContentTerms(query).toSet();
  if (qTokens.isEmpty || entries.isEmpty) return null;
  PhrasingEntry? best;
  var bestScore = 0.0;
  for (final entry in entries) {
    final pTokens = assistantContentTerms(entry.text).toSet();
    final shared = qTokens.intersection(pTokens).length;
    if (shared < 1) continue;
    final score = shared / qTokens.length;
    if (score > bestScore) {
      bestScore = score;
      best = entry;
    }
  }
  return bestScore >= 0.5 ? best : null;
}
